23	
24	func initSlogDefault() {
25		level, err := parseSlogLevel(viper.GetString("log-level"))
26		if err != nil {
27			slog.Warn("invalid log-level value, defaulting to info", "error", err)
28		}
29		slog.SetDefault(newLogger(level, os.Stderr))
30	}
31	
32	var (
33		rootCmd = &cobra.Command{
34			Use:   "memos",
35			Short: `An open source, lightweight note-taking service. Easily capture and share your great thoughts.`,
36			Run: func(_ *cobra.Command, _ []string) {
37				instanceProfile := &profile.Profile{
38					Demo:        viper.GetBool("demo"),
39					Addr:        viper.GetString("addr"),
40					Port:        viper.GetInt("port"),
41					UNIXSock:    viper.GetString("unix-sock"),
42					Data:        viper.GetString("data"),
43					Driver:      viper.GetString("driver"),
44					DSN:         viper.GetString("dsn"),
45					InstanceURL: viper.GetString("instance-url"),
46				}
47				instanceProfile.Version = version.GetCurrentVersion()
48				instanceProfile.Commit = version.Commit
49				webhook.AllowPrivateIPs = viper.GetBool("allow-private-webhooks")
50	
51				if err := instanceProfile.Validate(); err != nil {
52					slog.Error("failed to validate profile", "error", err)
53					return
54				}
55	
56				ctx, cancel := context.WithCancel(context.Background())
57				dbDriver, err := db.NewDBDriver(instanceProfile)
58				if err != nil {
59					cancel()
60					slog.Error("failed to create db driver", "error", err)
61					return
62				}
63	
64				storeInstance := store.New(dbDriver, instanceProfile)
65				if err := storeInstance.Migrate(ctx); err != nil {
66					cancel()
67					slog.Error("failed to migrate", "error", err)
68					return
69				}
70				if err := storeInstance.LoadDeploymentConfiguration(ctx); err != nil {
71					cancel()
72					slog.Error("failed to load deployment configuration", "error", err)
73					return
74				}
75	
76				s, err := server.NewServer(ctx, instanceProfile, storeInstance)
77				if err != nil {
78					cancel()
79					slog.Error("failed to create server", "error", err)
80					return
81				}
82	
83				c := make(chan os.Signal, 1)
84				// Trigger graceful shutdown on SIGINT or SIGTERM.
85				// The default signal sent by the `kill` command is SIGTERM,
86				// which is taken as the graceful shutdown signal for many systems, eg., Kubernetes, Gunicorn.
87				signal.Notify(c, os.Interrupt, syscall.SIGTERM)
88	
89				if err := s.Start(ctx); err != nil {
90					if err != http.ErrServerClosed {
91						slog.Error("failed to start server", "error", err)
92						cancel()
93						return
94					}
95				}
96	
97				printGreetings(instanceProfile)
98	
99				go func() {
100					<-c
101					s.Shutdown(ctx)
102					cancel()
103				}()
104	
105				// Wait for CTRL-C.
106				<-ctx.Done()
107			},
108		}
109		versionCmd = &cobra.Command{
110			Use:   "version",
111			Short: "Print the current Memos version",
112			Run: func(_ *cobra.Command, _ []string) {
113				fmt.Println(version.GetCurrentVersion())
114			},
115		}
116	)
117	
118	func init() {
119		cobra.OnInitialize(initSlogDefault)
120	
121		viper.SetDefault("demo", false)
122		viper.SetDefault("driver", "sqlite")
123		viper.SetDefault("port", 8081)
124	
125		rootCmd.PersistentFlags().Bool("demo", false, "enable demo mode")
126		rootCmd.PersistentFlags().String("addr", "", "address of server")
127		rootCmd.PersistentFlags().Int("port", 8081, "port of server")
128		rootCmd.PersistentFlags().String("unix-sock", "", "path to the unix socket, overrides --addr and --port")
129		rootCmd.PersistentFlags().String("data", "", "data directory")
130		rootCmd.PersistentFlags().String("driver", "sqlite", "database driver")
131		rootCmd.PersistentFlags().String("dsn", "", "database source name(aka. DSN)")
132		rootCmd.PersistentFlags().String("instance-url", "", "the url of your memos instance")
133		rootCmd.PersistentFlags().Bool("allow-private-webhooks", false, "allow webhook URLs to resolve to private/reserved IP addresses")
134		rootCmd.PersistentFlags().String("log-level", "info", "log verbosity level (debug, info, warn, error)")
135	
136		if err := viper.BindPFlag("demo", rootCmd.PersistentFlags().Lookup("demo")); err != nil {
137			panic(err)
138		}
139		if err := viper.BindPFlag("addr", rootCmd.PersistentFlags().Lookup("addr")); err != nil {
140			panic(err)
141		}
142		if err := viper.BindPFlag("port", rootCmd.PersistentFlags().Lookup("port")); err != nil {
143			panic(err)
144		}
145		if err := viper.BindPFlag("unix-sock", rootCmd.PersistentFlags().Lookup("unix-sock")); err != nil {
146			panic(err)
147		}
148		if err := viper.BindPFlag("data", rootCmd.PersistentFlags().Lookup("data")); err != nil {
149			panic(err)
150		}
151		if err := viper.BindPFlag("driver", rootCmd.PersistentFlags().Lookup("driver")); err != nil {
152			panic(err)
153		}
154		if err := viper.BindPFlag("dsn", rootCmd.PersistentFlags().Lookup("dsn")); err != nil {
155			panic(err)
156		}
157		if err := viper.BindPFlag("instance-url", rootCmd.PersistentFlags().Lookup("instance-url")); err != nil {
158			panic(err)
159		}
160		if err := viper.BindPFlag("allow-private-webhooks", rootCmd.PersistentFlags().Lookup("allow-private-webhooks")); err != nil {
161			panic(err)
162		}
163		if err := viper.BindPFlag("log-level", rootCmd.PersistentFlags().Lookup("log-level")); err != nil {
164			panic(err)
165		}
166	
167		viper.SetEnvPrefix("memos")
168		viper.SetEnvKeyReplacer(strings.NewReplacer("-", "_"))
169		viper.AutomaticEnv()
170	
171		rootCmd.AddCommand(versionCmd)
172	}
173	
174	func printGreetings(profile *profile.Profile) {
175		fmt.Printf("Memos %s started successfully!\n", profile.Version)
176	
177		if profile.Demo {
178			fmt.Fprint(os.Stderr, "Development mode is enabled\n")
179			if profile.DSN != "" {
180				fmt.Fprintf(os.Stderr, "Database: %s\n", profile.DSN)
181			}
182		}
183	
184		// Server information
185		fmt.Printf("Data directory: %s\n", profile.Data)
186		fmt.Printf("Database driver: %s\n", profile.Driver)
187	
188		// Connection information
189		if len(profile.UNIXSock) == 0 {
190			if len(profile.Addr) == 0 {
191				fmt.Printf("Server running on port %d\n", profile.Port)
192				fmt.Printf("Access your memos at: http://localhost:%d\n", profile.Port)
193			} else {
194				fmt.Printf("Server running on %s:%d\n", profile.Addr, profile.Port)
195				fmt.Printf("Access your memos at: http://%s:%d\n", profile.Addr, profile.Port)
196			}
197		} else {
198			fmt.Printf("Server running on unix socket: %s\n", profile.UNIXSock)
199		}
200	
201		// Access mode is derived from instance_url: set = public, unset = private.
202		accessMode := "private"
203		if profile.AllowAnonymous() {
204			accessMode = "public"
205		}
206		fmt.Printf("Access mode: %s\n", accessMode)
207	
208		fmt.Println()
209		fmt.Printf("Documentation: %s\n", "https://usememos.com")
210		fmt.Printf("Source code: %s\n", "https://github.com/usememos/memos")
211		fmt.Println("\nHappy note-taking!")
212	}
213	
214	func main() {
215		if err := rootCmd.Execute(); err != nil {
216			os.Exit(1)
217		}
218	}
